//! Numeric state codes. This does not build: version 2 added a
//! variant the match does not cover.

pub use status::State;

pub fn code(state: State) -> u8 {
    match state {
        State::Live => 1,
        State::Paused => 2,
    }
}

//! Numeric state codes.

pub use status::State;

pub fn code(state: State) -> u8 {
    match state {
        State::Live => 1,
        State::Paused => 2,
    }
}

//! Numeric state codes.

pub use status::State;

pub fn code(state: State) -> u8 {
    match state {
        State::Live => 1,
        State::Paused => 2,
        State::Draft => 1,
    }
}

//! Numeric state codes.

pub use status::State;

pub fn code(state: State) -> u8 {
    match state {
        State::Live => 1,
        State::Paused => 2,
        State::Draft => 0,
    }
}

//! Numeric state codes.

pub use status::State;

pub fn code(state: State) -> u8 {
    match state {
        State::Live => 9,
        State::Paused => 2,
        State::Draft => 0,
    }
}

